use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclstruct! {
# [doc = " A converter that decodes a byte stream into Unicode according to a"] # [doc = " character encoding in a streaming (incremental) manner."] # [doc = ""] # [doc = " The various `decode_*` methods take an input buffer (`src`) and an output"] # [doc = " buffer `dst` both of which are caller-allocated. There are variants for"] # [doc = " both UTF-8 and UTF-16 output buffers."] # [doc = ""] # [doc = " A `decode_*` method decodes bytes from `src` into Unicode characters stored"] # [doc = " into `dst` until one of the following three things happens:"] # [doc = ""] # [doc = " 1. A malformed byte sequence is encountered (`*_without_replacement`"] # [doc = "    variants only)."] # [doc = ""] # [doc = " 2. The output buffer has been filled so near capacity that the decoder"] # [doc = "    cannot be sure that processing an additional byte of input wouldn't"] # [doc = "    cause so much output that the output buffer would overflow."] # [doc = ""] # [doc = " 3. All the input bytes have been processed."] # [doc = ""] # [doc = " The `decode_*` method then returns tuple of a status indicating which one"] # [doc = " of the three reasons to return happened, how many input bytes were read,"] # [doc = " how many output code units (`u8` when decoding into UTF-8 and `u16`"] # [doc = " when decoding to UTF-16) were written (except when decoding into `String`,"] # [doc = " whose length change indicates this), and in the case of the"] # [doc = " variants performing replacement, a boolean indicating whether an error was"] # [doc = " replaced with the REPLACEMENT CHARACTER during the call."] # [doc = ""] # [doc = " The number of bytes \"written\" is what's logically written. Garbage may be"] # [doc = " written in the output buffer beyond the point logically written to."] # [doc = " Therefore, if you wish to decode into an `&mut str`, you should use the"] # [doc = " methods that take an `&mut str` argument instead of the ones that take an"] # [doc = " `&mut [u8]` argument. The former take care of overwriting the trailing"] # [doc = " garbage to ensure the UTF-8 validity of the `&mut str` as a whole, but the"] # [doc = " latter don't."] # [doc = ""] # [doc = " In the case of the `*_without_replacement` variants, the status is a"] # [doc = " [`DecoderResult`][1] enumeration (possibilities `Malformed`, `OutputFull` and"] # [doc = " `InputEmpty` corresponding to the three cases listed above)."] # [doc = ""] # [doc = " In the case of methods whose name does not end with"] # [doc = " `*_without_replacement`, malformed sequences are automatically replaced"] # [doc = " with the REPLACEMENT CHARACTER and errors do not cause the methods to"] # [doc = " return early."] # [doc = ""] # [doc = " When decoding to UTF-8, the output buffer must have at least 4 bytes of"] # [doc = " space. When decoding to UTF-16, the output buffer must have at least two"] # [doc = " UTF-16 code units (`u16`) of space."] # [doc = ""] # [doc = " When decoding to UTF-8 without replacement, the methods are guaranteed"] # [doc = " not to return indicating that more output space is needed if the length"] # [doc = " of the output buffer is at least the length returned by"] # [doc = " [`max_utf8_buffer_length_without_replacement()`][2]. When decoding to UTF-8"] # [doc = " with replacement, the length of the output buffer that guarantees the"] # [doc = " methods not to return indicating that more output space is needed is given"] # [doc = " by [`max_utf8_buffer_length()`][3]. When decoding to UTF-16 with"] # [doc = " or without replacement, the length of the output buffer that guarantees"] # [doc = " the methods not to return indicating that more output space is needed is"] # [doc = " given by [`max_utf16_buffer_length()`][4]."] # [doc = ""] # [doc = " The output written into `dst` is guaranteed to be valid UTF-8 or UTF-16,"] # [doc = " and the output after each `decode_*` call is guaranteed to consist of"] # [doc = " complete characters. (I.e. the code unit sequence for the last character is"] # [doc = " guaranteed not to be split across output buffers.)"] # [doc = ""] # [doc = " The boolean argument `last` indicates that the end of the stream is reached"] # [doc = " when all the bytes in `src` have been consumed."] # [doc = ""] # [doc = " A `Decoder` object can be used to incrementally decode a byte stream."] # [doc = ""] # [doc = " During the processing of a single stream, the caller must call `decode_*`"] # [doc = " zero or more times with `last` set to `false` and then call `decode_*` at"] # [doc = " least once with `last` set to `true`. If `decode_*` returns `InputEmpty`,"] # [doc = " the processing of the stream has ended. Otherwise, the caller must call"] # [doc = " `decode_*` again with `last` set to `true` (or treat a `Malformed` result as"] # [doc = "  a fatal error)."] # [doc = ""] # [doc = " Once the stream has ended, the `Decoder` object must not be used anymore."] # [doc = " That is, you need to create another one to process another stream."] # [doc = ""] # [doc = " When the decoder returns `OutputFull` or the decoder returns `Malformed` and"] # [doc = " the caller does not wish to treat it as a fatal error, the input buffer"] # [doc = " `src` may not have been completely consumed. In that case, the caller must"] # [doc = " pass the unconsumed contents of `src` to `decode_*` again upon the next"] # [doc = " call."] # [doc = ""] # [doc = " [1]: enum.DecoderResult.html"] # [doc = " [2]: #method.max_utf8_buffer_length_without_replacement"] # [doc = " [3]: #method.max_utf8_buffer_length"] # [doc = " [4]: #method.max_utf16_buffer_length"] # [doc = ""] # [doc = " # Infinite loops"] # [doc = ""] # [doc = " When converting with a fixed-size output buffer whose size is too small to"] # [doc = " accommodate one character or (when applicable) one numeric character"] # [doc = " reference of output, an infinite loop ensues. When converting with a"] # [doc = " fixed-size output buffer, it generally makes sense to make the buffer"] # [doc = " fairly large (e.g. couple of kilobytes)."] pub struct Decoder { encoding : & 'static Encoding , variant : VariantDecoder , life_cycle : DecoderLifeCycle , }
}